-- Phase 15: Internal fictional court docket, counsel and hearing registry.
CREATE TABLE court_lawyers (user_id TEXT PRIMARY KEY REFERENCES users(id), license_number TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','suspended')), approved_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE court_cases (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, plaintiff_id TEXT NOT NULL REFERENCES users(id), defendant_id TEXT REFERENCES users(id), defendant_name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('civil','commercial','administrative','family','criminal')), title TEXT NOT NULL, statement TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'filed' CHECK(status IN ('filed','review','scheduled','heard','judged','closed')), assigned_judge TEXT REFERENCES users(id), judgment TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_court_plaintiff ON court_cases(plaintiff_id,created_at);
CREATE INDEX idx_court_defendant ON court_cases(defendant_id,created_at);
CREATE TABLE court_counsel (case_id TEXT NOT NULL REFERENCES court_cases(id), lawyer_id TEXT NOT NULL REFERENCES users(id), client_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','accepted','rejected','revoked')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(case_id,lawyer_id,client_id));
CREATE TABLE court_hearings (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES court_cases(id), starts_at TEXT NOT NULL, location TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE court_events (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES court_cases(id), actor_id TEXT NOT NULL REFERENCES users(id), event_type TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
